commands.run:
node scripts/release-candidate.js --verify .artifacts/release/candidate.json "$RELEASE_TAG"
node --input-type=module -e '
  import { readFileSync, appendFileSync } from "node:fs";
  import path from "node:path";
  const candidate = JSON.parse(readFileSync(".artifacts/release/candidate.json", "utf8"));
  appendFileSync(process.env.GITHUB_ENV, `GGACTION_PACKAGE_SPEC=${path.resolve(".artifacts/release", candidate.filename)}\n`);
'

